import { test, expect } from '@playwright/test';

// Generated by Specwright AI from "MediBook Patient Portal Requirements v1.2"
// Covers: REQ-01 (login + lockout), REQ-03 (booking window), REQ-04 (slots), REQ-08 (confirmation)

const PATIENT = { email: 'patient@medibook.test', password: 'Clinic#2026' };

async function login(page, email, password) {
  await page.goto('/');
  await page.getByLabel('Email').fill(email);
  await page.getByLabel('Password').fill(password);
  await page.click('#login-btn');
}

test('patient can book an appointment', async ({ page }) => {
  await login(page, PATIENT.email, PATIENT.password);
  await expect(page.getByRole('heading', { name: 'Welcome back' })).toBeVisible();

  await page.getByRole('button', { name: 'Book appointment' }).click();

  const today = new Date().toISOString().slice(0, 10);
  await page.getByLabel('Appointment date').fill(today);

  // wait for available time slots to load
  await page.waitForTimeout(1000);
  const slots = await page.$$('.slot');
  await slots[0].click();

  await page.getByLabel('Reason for visit').fill('Annual check-up');
  await page.getByRole('button', { name: 'Confirm booking' }).click();

  await expect(page.getByRole('heading', { name: 'Appointment confirmed' })).toBeVisible();
  const ref = await page.getByTestId('booking-ref').textContent();
  expect(ref).toMatch(/^MB-\d{5}$/);
});

test('account locks after 3 failed login attempts', async ({ page }) => {
  for (let i = 0; i < 3; i++) {
    await login(page, PATIENT.email, 'wrong-password1');
  }
  expect(await page.locator('.error-banner').isVisible).toBeTruthy();
});
